"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[76909],{3331:(e,i,a)=>{a.d(i,{R:()=>o,x:()=>l});var r=a(36672);const t={},n=r.createContext(t);function o(e){const i=r.useContext(n);return r.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function l(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),r.createElement(n.Provider,{value:i},e.children)}},88184:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>c,contentTitle:()=>l,default:()=>d,frontMatter:()=>o,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"2023/03/31","title":"31","description":"March 31, 2023","source":"@site/i18n/ro/docusaurus-plugin-content-docs/current/2023/03/31.md","sourceDirName":"2023/03","slug":"/2023/03/31","permalink":"/ro/2023/03/31","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/ro/docusaurus-plugin-content-docs//current/2023/03/31.md","tags":[],"version":"current","frontMatter":{"localized_date":"31 martie 2023","top_news":"Proiectul de lege al SUA privind interzicerea accesului la internet ridic\u0103 probleme pentru VPN-uri \u0219i TikTok"},"sidebar":"defaultSidebar","previous":{"title":"01","permalink":"/ro/2023/04/01"},"next":{"title":"2023-03-30","permalink":"/ro/2023/03/30"}}');var t=a(23420),n=a(3331);const o={localized_date:"31 martie 2023",top_news:"Proiectul de lege al SUA privind interzicerea accesului la internet ridic\u0103 probleme pentru VPN-uri \u0219i TikTok"},l=void 0,c={},u=[{value:"March 31, 2023",id:"march-31-2023",level:2},{value:"Proiectul de lege al SUA privind interzicerea accesului la internet ridic\u0103 probleme pentru VPN-uri \u0219i TikTok",id:"proiectul-de-lege-al-sua-privind-interzicerea-accesului-la-internet-ridic\u0103-probleme-pentru-vpn-uri-\u0219i-tiktok",level:2},{value:"Opinii amestecate privind valoarea Y Combinator pentru startup-uri",id:"opinii-amestecate-privind-valoarea-y-combinator-pentru-startup-uri",level:2},{value:"Scratch: Limbajul popular de programare vizual\u0103 pentru copii",id:"scratch-limbajul-popular-de-programare-vizual\u0103-pentru-copii",level:2},{value:"Challenges &amp; Tradeoffs in LED Lighting Technology (Provoc\u0103ri \u0219i compromisuri \xeen tehnologia de iluminat cu LED-uri)",id:"challenges--tradeoffs-in-led-lighting-technology-provoc\u0103ri-\u0219i-compromisuri-\xeen-tehnologia-de-iluminat-cu-led-uri",level:2},{value:"Peste jum\u0103tate din pachetele NPM noi sunt spam",id:"peste-jum\u0103tate-din-pachetele-npm-noi-sunt-spam",level:2},{value:"US Proposes Bills with Threats to Tech Freedom &amp; Privacy (SUA propune proiecte de lege care amenin\u021b\u0103 libertatea \u0219i confiden\u021bialitatea \xeen domeniul tehnologiei)",id:"us-proposes-bills-with-threats-to-tech-freedom--privacy-sua-propune-proiecte-de-lege-care-amenin\u021b\u0103-libertatea-\u0219i-confiden\u021bialitatea-\xeen-domeniul-tehnologiei",level:2},{value:"Open-Source 3D Rendering Engine pentru educa\u021bie \u0219i integrare",id:"open-source-3d-rendering-engine-pentru-educa\u021bie-\u0219i-integrare",level:2},{value:"Google neag\u0103 c\u0103 a folosit ChatGPT de la OpenAI pentru a-l antrena pe Bard",id:"google-neag\u0103-c\u0103-a-folosit-chatgpt-de-la-openai-pentru-a-l-antrena-pe-bard",level:2},{value:"Twitter API neglijat, nemul\u021bumirea utilizatorilor cre\u0219te",id:"twitter-api-neglijat-nemul\u021bumirea-utilizatorilor-cre\u0219te",level:2},{value:"Directorul sindicatului poli\u021biei din San Jose, acuzat de contraband\u0103 cu droguri",id:"directorul-sindicatului-poli\u021biei-din-san-jose-acuzat-de-contraband\u0103-cu-droguri",level:2}];function s(e){const i={a:"a",h2:"h2",p:"p",...(0,n.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(i.h2,{id:"march-31-2023",children:"March 31, 2023"}),"\n",(0,t.jsx)(i.h2,{id:"proiectul-de-lege-al-sua-privind-interzicerea-accesului-la-internet-ridic\u0103-probleme-pentru-vpn-uri-\u0219i-tiktok",children:"Proiectul de lege al SUA privind interzicerea accesului la internet ridic\u0103 probleme pentru VPN-uri \u0219i TikTok"}),"\n",(0,t.jsxs)(i.p,{children:["Un proiect de lege de interzicere din SUA, sus\u021binut de Casa Alb\u0103 \u0219i care vizeaz\u0103 reglementarea internetului, ar putea face ca VPN-urile s\u0103 fie ilegale, s\u0103 acorde amenzi de p\xe2n\u0103 la 1 milion de dolari \u0219i 20 de ani de \xeenchisoare \u0219i s\u0103 fie considerat un atac la adresa libert\u0103\u021bilor civile. Proiectul de lege beneficiaz\u0103 de sprijin bipartizan, concentr\xe2ndu-se pe preocup\u0103rile de securitate na\u021bional\u0103 legate de China \u0219i pe limitarea afacerilor cu aceast\u0103 \u021bar\u0103. Este posibil ca UE s\u0103 nu urmeze tendin\u021ba SUA, deoarece \u021b\u0103rile au propria structur\u0103 juridic\u0103, iar interdic\u021bia TikTok ar putea duce la resentimente \xeen r\xe2ndul tinerilor \u0219i la represalii \xeempotriva guvernului american. Criticii interdic\u021biei sus\u021bin c\u0103 aceasta amenin\u021b\u0103 via\u021ba privat\u0103 a indivizilor \u0219i libertatea de exprimare \u0219i de exprimare.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35366955",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://www.youtube.com/watch?v=FWQGA_n5Z4M",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"opinii-amestecate-privind-valoarea-y-combinator-pentru-startup-uri",children:"Opinii amestecate privind valoarea Y Combinator pentru startup-uri"}),"\n",(0,t.jsxs)(i.p,{children:["Opiniile privind valoarea Y Combinator (YC) pentru startup-uri sunt mixte, \xeen func\u021bie de perspectivele \u0219i nevoile individuale. \xcen timp ce unii apreciaz\u0103 re\u021beaua \u0219i mentoratul oferite de YC, al\u021bii critic\u0103 sfaturile \u0219i concentrarea pe obiective pe termen scurt. Reputa\u021bia \u0219i brandul YC pot ajuta la str\xe2ngerea de fonduri, dar acordul SAFE f\u0103r\u0103 plafon \u0219i accentul pus pe extinderea cu orice pre\u021b s-ar putea s\u0103 nu se potriveasc\u0103 tuturor fondatorilor. Importan\u021ba construirii comunit\u0103\u021bii \u0219i a conexiunilor personale \xeen formatul doar la distan\u021b\u0103 este, de asemenea, dezb\u0103tut\u0103. \xcen cele din urm\u0103, valoarea YC depinde de capacitatea unui fondator de a utiliza resursele sale pentru a maximiza \u0219ansele de succes.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35373019",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://acecreamu.substack.com/p/is-y-combinator-worth-the-money",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"scratch-limbajul-popular-de-programare-vizual\u0103-pentru-copii",children:"Scratch: Limbajul popular de programare vizual\u0103 pentru copii"}),"\n",(0,t.jsxs)(i.p,{children:["Scratch este un limbaj de programare vizual popular destinat copiilor, care folose\u0219te blocuri colorate \xeen loc de coduri bazate pe text pentru a-i ajuta s\u0103 \xeenve\u021be concepte de programare. Programul include principii de programare de baz\u0103, cum ar fi variabilele, listele, structurile de flux de control if/else \u0219i looping \u0219i concuren\u021ba bazat\u0103 pe evenimente. Scratch are o abordare simpl\u0103 \u0219i u\u0219or de utilizat pentru a-i \xeencuraja pe copii s\u0103 exploreze calculul \xeentr-un mod creativ, precum \u0219i un accent deosebit pe interac\u021biunea \xeentre colegi \u0219i pe partajarea muncii pentru a primi feedback. Comunitatea Scratch este una dintre cele mai mari comunit\u0103\u021bi de codificare din lume, cu peste 103 milioane de utilizatori \u0219i 123 de milioane de proiecte partajate pe platform\u0103. De\u0219i exist\u0103 \xeengrijor\u0103ri cu privire la re\u021belele de socializare nereglementate \u0219i la faptul c\u0103 copiii joac\u0103 jocuri video \xeen loc s\u0103 foloseasc\u0103 Scratch \xeen scopuri educa\u021bionale, instrumentul i-a inspirat pe mul\u021bi s\u0103 devin\u0103 interesa\u021bi de programare, cu proiecte care variaz\u0103 de la codificarea pentru \xeencep\u0103tori p\xe2n\u0103 la abilit\u0103\u021bi avansate de programare.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35373052",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://scratch.mit.edu/about",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"challenges--tradeoffs-in-led-lighting-technology-provoc\u0103ri-\u0219i-compromisuri-\xeen-tehnologia-de-iluminat-cu-led-uri",children:"Challenges & Tradeoffs in LED Lighting Technology (Provoc\u0103ri \u0219i compromisuri \xeen tehnologia de iluminat cu LED-uri)"}),"\n",(0,t.jsxs)(i.p,{children:["Becurile cu LED-uri prezint\u0103 provoc\u0103ri legate de defectarea rapid\u0103, redarea slab\u0103 a culorilor \u0219i a indicilor de similaritate spectral\u0103, surse de alimentare prost proiectate, supra\xeenc\u0103lzirea \u0219i un cost mai mare pentru iluminatul interior. Sursele de alimentare cu curent constant sunt necesare pentru iluminatul cu LED-uri, iar corpurile de iluminat trebuie s\u0103 fie proiectate diferit fa\u021b\u0103 de becurile cu incandescen\u021b\u0103 pentru a disipa c\u0103ldura. Exist\u0103 \xeengrijor\u0103ri cu privire la fiabilitatea \u0219i durabilitatea becurilor cu LED, de\u0219i sunt disponibile op\u021biuni de \xeenalt\u0103 calitate la un pre\u021b mai ridicat. Exist\u0103 provoc\u0103ri \xeen ceea ce prive\u0219te integrarea becurilor cu LED cu \xeentrerup\u0103toarele cu variator \u0219i asigurarea compatibilit\u0103\u021bii. P\xe2lp\xe2irea \u0219i lipsa de vivacitate a iluminatului cu LED-uri au dus la dezvoltarea unor noi sisteme de clasificare \u0219i a unor becuri cu LED-uri reglabile. \xcen general, tehnologia LED are poten\u021bial, dar necesit\u0103 o dezvoltare \u0219i o inovare continu\u0103.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35371750",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://nymag.com/strategist/article/led-light-bulbs-investigation.html",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"peste-jum\u0103tate-din-pachetele-npm-noi-sunt-spam",children:"Peste jum\u0103tate din pachetele NPM noi sunt spam"}),"\n",(0,t.jsxs)(i.p,{children:["Mai mult de jum\u0103tate din noile pachete npm trimise sunt spam, multe dintre ele con\u021bin\xe2nd link-uri c\u0103tre site-uri web mali\u021bioase sau oferind gratuit\u0103\u021bi false precum Fortnite V-Bucks. Se crede c\u0103 aceast\u0103 cre\u0219tere a spam-ului este legat\u0103 de taberele de preg\u0103tire \xeen domeniul cod\u0103rii, unde studen\u021bii sunt \xeencuraja\u021bi s\u0103 publice pachete chiar dac\u0103 nu fac nimic. Responden\u021bii au sugerat solu\u021bii precum procese de testare automatizate \u0219i un model web-of-trust. Aceast\u0103 problem\u0103 eviden\u021biaz\u0103 natura complex\u0103 a eticii \xeen industria de dezvoltare de software \u0219i tensiunile dintre libertatea de exprimare \u0219i drepturile de proprietate privat\u0103. Cercet\u0103torii \xeen domeniul securit\u0103\u021bii au identificat prezen\u021ba pachetelor spam \xeen \xeentregul registru npm \u0219i investigheaz\u0103 \xeen continuare.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35370728",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://blog.sandworm.dev/one-in-two-new-npm-packages-is-seo-spam-right-now",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"us-proposes-bills-with-threats-to-tech-freedom--privacy-sua-propune-proiecte-de-lege-care-amenin\u021b\u0103-libertatea-\u0219i-confiden\u021bialitatea-\xeen-domeniul-tehnologiei",children:"US Proposes Bills with Threats to Tech Freedom & Privacy (SUA propune proiecte de lege care amenin\u021b\u0103 libertatea \u0219i confiden\u021bialitatea \xeen domeniul tehnologiei)"}),"\n",(0,t.jsxs)(i.p,{children:['Guvernul SUA a propus un proiect de lege care ar conferi o putere f\u0103r\u0103 precedent de a interzice orice tehnologie str\u0103in\u0103 pe care o consider\u0103 o "amenin\u021bare la adresa securit\u0103\u021bii na\u021bionale", ceea ce \xeei face pe unii s\u0103 sus\u021bin\u0103 c\u0103 ar putea duce la puteri de cenzur\u0103 asem\u0103n\u0103toare cu cele din China \u0219i c\u0103 ar fi mult mai extins\u0103 dec\xe2t se credea ini\u021bial. Exist\u0103, de asemenea, o dezbatere cu privire la interzicerea aplica\u021biilor de socializare de\u021binute de chinezi, unii sus\u021bin\xe2nd c\u0103 este o pant\u0103 alunecoas\u0103 spre cenzurarea informa\u021biilor, \xeen timp ce al\u021bii sus\u021bin c\u0103 este necesar pentru a \xeempiedica companiile chineze s\u0103 fure tehnologie american\u0103 \u0219i s\u0103 colecteze informa\u021bii \xeen scopuri de spionaj. Legea RESTRICT este o propunere de lege care ar putea fi folosit\u0103 pentru a interzice TikTok \u0219i VPN-urile, iar criticii sus\u021bin c\u0103 ar putea \xeenc\u0103lca Primul Amendament. Senatorii republicani au propus, de asemenea, interzicerea utiliz\u0103rii de c\u0103tre angaja\u021bii federali a aplica\u021biilor de socializare de\u021binute de companii chineze\u0219ti, din cauza preocup\u0103rilor legate de spionaj \u0219i supraveghere. Unii comentatori sugereaz\u0103 c\u0103 legisla\u021bia echivaleaz\u0103 cu protec\u021bionism din partea guvernului, \xeen timp ce al\u021bii sus\u021bin c\u0103 dezvoltarea social media d\u0103uneaz\u0103 s\u0103n\u0103t\u0103\u021bii mentale \u0219i contribuie la manipularea opiniei publice.\n',(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35369075",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://www.vice.com/en/article/4a3ddb/restrict-act-insanely-broad-ban-tiktok-vpns",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"open-source-3d-rendering-engine-pentru-educa\u021bie-\u0219i-integrare",children:"Open-Source 3D Rendering Engine pentru educa\u021bie \u0219i integrare"}),"\n",(0,t.jsxs)(i.p,{children:["Un motor de randare 3D open-source StratusGFX a fost lansat de un dezvoltator pentru ca oamenii s\u0103 integreze codul s\u0103u de randare \xeen alte motoare sau s\u0103 \xeel foloseasc\u0103 ca resurs\u0103 educa\u021bional\u0103. Capacit\u0103\u021bile sale includ reflexii \xeen timp real, umbre \u0219i suport complet pentru umbrire PBR, dar \xeen prezent suport\u0103 doar OpenGL. Creatorul s\u0103u ia \xeen considerare posibilitatea de a porta randarea la Vulkan pentru a \xeembun\u0103t\u0103\u021bi compatibilitatea \xeentre platforme. Motorul StratusGFX este conceput pentru a maximiza realismul, dar cu capacit\u0103\u021bi de compromis de rezerv\u0103 pentru hardware mai pu\u021bin puternic, iar arhitectura sa este disponibil\u0103 pe Github pentru Windows \u0219i Linux. Motorul se afl\u0103 \xeen stadiul de pre-lansare/beta-lansare, \u0219i trebuie s\u0103 v\u0103 a\u0219tepta\u021bi la bug-uri \u0219i instabilitate semnificative.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35370284",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://github.com/KTStephano/StratusGFX",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"google-neag\u0103-c\u0103-a-folosit-chatgpt-de-la-openai-pentru-a-l-antrena-pe-bard",children:"Google neag\u0103 c\u0103 a folosit ChatGPT de la OpenAI pentru a-l antrena pe Bard"}),"\n",(0,t.jsxs)(i.p,{children:["Google neag\u0103 c\u0103 a folosit OpenAI's ChatGPT pentru a antrena Bard, un nou model de limbaj. Au fost exprimate \xeengrijor\u0103ri cu privire la etica antren\u0103rii unui model lingvistic de mari dimensiuni cu rezultatul unui alt LLM controlat comercial. Termenii de serviciu ai OpenAI interzic antrenarea modelelor concurente prin intermediul ie\u0219irilor ML ale acestuia, dar Google nu este obligat s\u0103 respecte aceast\u0103 prevedere. Un fost angajat al Google a afirmat c\u0103 a folosit datele OpenAI, dar Google neag\u0103 acest lucru. Materialul generat de AI nu poate fi protejat prin drepturi de autor, iar antrenarea pe alte rezultate ale modelului este permis\u0103. Unii sus\u021bin c\u0103 furtul din ChatGPT ar putea fi justificat din punct de vedere moral, deoarece a fost ob\u021binut \xeen grup, dar antrenarea modelelor pe alte date generate de AI ar putea impune utilizarea de date proaste.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35370915",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://twitter.com/steventey/status/1641267979399704576",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"twitter-api-neglijat-nemul\u021bumirea-utilizatorilor-cre\u0219te",children:"Twitter API neglijat, nemul\u021bumirea utilizatorilor cre\u0219te"}),"\n",(0,t.jsxs)(i.p,{children:["Se pare c\u0103 API-ul Twitter este l\u0103sat ne\xeentre\u021binut, ceea ce duce la probleme de instabilitate pentru utilizatori. Unii utilizatori au raportat c\u0103 se simt \xeenstr\u0103ina\u021bi de serviciu din cauza sc\u0103derii con\u021binutului de lucr\u0103ri \u0219tiin\u021bifice \u0219i a cre\u0219terii propor\u021biei de con\u021binut inflamator sau ofensator. Multe platforme de socializare utilizeaz\u0103 fluxuri algoritmice, dar valorile implicite sunt importante, deoarece influen\u021beaz\u0103 comportamentul utilizatorilor. Utilizatorii Twitter se confrunt\u0103 cu probleme precum erori interne ale serverului \u0219i dificult\u0103\u021bi de accesare a site-ului, ceea ce i-a determinat pe unii s\u0103 treac\u0103 la platforme alternative, cum ar fi Mastodon. Recentele probleme de instabilitate ale Twitter i-au determinat pe unii utilizatori s\u0103 \xee\u0219i reduc\u0103 utilizarea. \xcen ciuda acestor \xeengrijor\u0103ri, unii consider\u0103 c\u0103 cre\u0219terea Twitter sub conducerea lui Musk sugereaz\u0103 c\u0103 platforma va continua s\u0103 prospere, cu sau f\u0103r\u0103 utilizatorii s\u0103i devota\u021bi. Decizia lui Elon Musk de a restric\u021biona accesul la API-ul Twitter st\xe2rne\u0219te controverse, criticii acuz\xe2ndu-l c\u0103 a dus \xeen mod inten\u021bionat Twitter la pr\u0103bu\u0219ire. API-ul Twitter este acum efectiv ne\xeentre\u021binut, un singur angajat post\xe2nd \xeen mod regulat pe forumul Twitter Developers \u0219i concentr\xe2ndu-se exclusiv pe API-ul pentru anun\u021buri.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35370152",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://snarfed.org/the-twitter-api-is-now-effectively-unmaintained",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(i.h2,{id:"directorul-sindicatului-poli\u021biei-din-san-jose-acuzat-de-contraband\u0103-cu-droguri",children:"Directorul sindicatului poli\u021biei din San Jose, acuzat de contraband\u0103 cu droguri"}),"\n",(0,t.jsxs)(i.p,{children:["Directorul executiv al Asocia\u021biei ofi\u021berilor de poli\u021bie din San Jose, Sonia Rosa Segovia, a fost acuzat\u0103 de contraband\u0103 cu fentanil \xeen SUA \u0219i de gestionarea unei afaceri cu droguri par\u021bial din birou. Segovia ar fi folosit adresa asocia\u021biei pentru a trimite pachete clien\u021bilor \u0219i ar fi discutat cu furnizorii s\u0103i despre afacerile poli\u021biei. Cel pu\u021bin unul dintre clien\u021bii s\u0103i a murit din cauza unei supradoze, iar aceasta se confrunt\u0103 cu mai multe acuza\u021bii legate de droguri. Alte cazuri de ofi\u021beri de poli\u021bie implica\u021bi \xeen traficul de droguri au ridicat \xeentreb\u0103ri cu privire la rolul for\u021belor de ordine \xeen comer\u021bul ilegal cu droguri, unii suger\xe2nd legalizarea ca solu\u021bie. Conversa\u021bia \xeen jurul legaliz\u0103rii drogurilor atinge, de asemenea, externalit\u0103\u021bile \u0219i nevoia de sisteme de sprijin. Un director executiv al sindicatului poli\u021biei din San Jose, Joanne Southerland, a fost, de asemenea, acuzat de trafic de droguri, la fel ca \u0219i Joanne Segovia, o angajat\u0103 a sindicatului poli\u021biei, care a fost pus\u0103 sub acuzare sub acuza\u021bia de import de metamfetamin\u0103 \xeen SUA. Aceste cazuri eviden\u021biaz\u0103 necesitatea unor solu\u021bii pentru a aborda traficul de droguri \u0219i dependen\u021ba de droguri, inclusiv schimb\u0103ri culturale \u0219i eforturi specifice de aplicare a legii.\n",(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35376488",children:"Hacker News Link"}),", ",(0,t.jsx)(i.a,{href:"https://www.washingtonexaminer.com/news/crime/san-jose-police-union-director-smuggle-fentanyl-charge",children:"Original Post"}),"."]})]})}function d(e={}){const{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,t.jsx)(i,{...e,children:(0,t.jsx)(s,{...e})}):s(e)}}}]);